package org.traccar.protocol;

import io.netty.channel.Channel;
import org.traccar.AbstractWireDecoder;
import org.traccar.session.UnitSession;
import org.traccar.NetworkMessage;
import org.traccar.Protocol;
import org.traccar.helper.FieldCursor;
import org.traccar.helper.GrammarComposer;
import org.traccar.helper.UnitsConverter;
import org.traccar.model.Position;

import java.net.SocketAddress;
import java.util.regex.Pattern;

public class Tr20ProtocolDecoder extends AbstractWireDecoder {

    public Tr20ProtocolDecoder(Protocol protocol) {
        super(protocol);
    }

    private static final Pattern PATTERN_PING = new GrammarComposer()
            .text("%%")
            .expression("[^,]+,")
            .number("(d+)")
            .compile();

    private static final Pattern PATTERN_DATA = new GrammarComposer()
            .text("%%")
            .expression("([^,]+),")              // id
            .expression("([AL]),")               // validity
            .number("(dd)(dd)(dd)")              // date (yymmdd)
            .number("(dd)(dd)(dd),")             // time (hhmmss)
            .expression("([NS])")
            .number("(dd)(dd.d+)")               // latitude
            .expression("([EW])")
            .number("(ddd)(dd.d+),")             // longitude
            .number("(d+),")                     // speed
            .number("(d+),")                     // course
            .number("(?:NA|[BFC]?(-?d+)[^,]*),") // temperature
            .number("(x{8}),")                   // status
            .number("(d+)")                      // event
            .any()
            .compile();

    @Override
    protected Object decode(
            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {

        FieldCursor parser = new FieldCursor(PATTERN_PING, (String) msg);
        if (parser.matches()) {
            if (channel != null) {
                channel.writeAndFlush(new NetworkMessage(
                        "&&" + parser.next() + "\r\n", remoteAddress)); // keep-alive response
            }
            return null;
        }

        parser = new FieldCursor(PATTERN_DATA, (String) msg);
        if (!parser.matches()) {
            return null;
        }

        Position position = new Position(wireName());

        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, parser.next());
        if (deviceSession == null) {
            return null;
        }
        position.setDeviceId(deviceSession.getDeviceId());

        position.setValid(parser.next().equals("A"));

        position.setTime(parser.nextDateTime());

        position.setLatitude(parser.nextCoordinate(FieldCursor.CoordinateFormat.HEM_DEG_MIN));
        position.setLongitude(parser.nextCoordinate(FieldCursor.CoordinateFormat.HEM_DEG_MIN));
        position.setSpeed(UnitsConverter.nauticalFromMetricSpeed(parser.nextDouble()));
        position.setCourse(parser.nextDouble());

        position.set(Position.PREFIX_TEMP + 1, parser.nextInt());
        position.set(Position.KEY_STATUS, parser.nextHexLong());
        position.set(Position.KEY_EVENT, parser.nextInt());

        return position;
    }

}

